arguments.command:
cd /tmp/shurik-workspace-38O8oO
for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --reverse --format='COMMIT %H%n%ci%n%B%n---END---' | awk -v br="friend/$b" '
    /^COMMIT / {sha=$2; next}
    /^[0-9]{4}-/ {ts=$0; next}
    /^Friend-Message: 1/ {fm=1; next}
    /^Episode: / {ep=$2; next}
    /^---END---/ {
      if (fm==1) print br, sha, ts, ep;
      fm=0; ep=""; next
    }
  '
done | grep "S07/E04" | sort -k3

cd /tmp/shurik-workspace-38O8oO && git fetch origin --prune 2>&1 | tail
# list S07/E04 commits all branches
for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --reverse --format='COMMIT %H%n%ci%n%B%n---END---' | awk -v br="friend/$b" '
    /^COMMIT / {sha=$2; next}
    /^[0-9]{4}-/ {ts=$0; next}
    /^Friend-Message: 1/ {fm=1; next}
    /^Episode: / {ep=$2; next}
    /^---END---/ {
      if (fm==1) print br, sha, ts, ep;
      fm=0; ep=""; next
    }
  '
done | grep "S07/E04" | sort -k3

cd /tmp/ross-main-wt && git fetch origin main && git merge --ff-only origin/main 2>&1 | tail
# Build set of transcribed SHAs
grep -rhoE "friend/[a-z]+ @ [0-9a-f]+" . --include='*.md' | sort -u > /tmp/transcribed.txt
# Build set of all Friend-Message commits
cd /tmp/shurik-workspace-38O8oO
for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --reverse --format='COMMIT %H%n%ci%n%B%n---END---' | awk -v br="friend/$b" '
    /^COMMIT / {sha=$2; next}
    /^[0-9]{4}-/ {ts=$0; next}
    /^Friend-Message: 1/ {fm=1; next}
    /^Episode: / {ep=$2; next}
    /^---END---/ {
      if (fm==1) print br, sha, ts, ep;
      fm=0; ep=""; next
    }
  '
done > /tmp/all_commits.txt
# find missing
python3 - <<'PY'
import re
trans=set()
for line in open('/tmp/transcribed.txt'):
    m=line.strip().split(' @ ')
    if len(m)==2: trans.add(m[1])
missing=[]
for line in open('/tmp/all_commits.txt'):
    parts=line.split()
    # br sha ts date? Actually format: br sha "YYYY-MM-DD HH:MM:SS +ZZZZ" ep
    # reconstruct
    m=re.match(r'(\S+) ([0-9a-f]+) (\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} [+-]\d{4}) (.+)', line.strip())
    if not m: 
        print("PARSEFAIL",line.strip()); continue
    br,sha,ts,ep=m.groups()
    if sha not in trans:
        missing.append((ts,sha,br,ep))
print("total commits", sum(1 for _ in open('/tmp/all_commits.txt')))
print("transcribed", len(trans))
print("missing", len(missing))
for m in missing[:50]:
    print(m)
PY
